import{_ as e,c as t,o as n,a0 as i}from"./chunks/framework.oTSD2LDJ.js";const u=JSON.parse('{"title":"官方插件","description":"","frontmatter":{"title":"官方插件","editLink":true},"headers":[],"relativePath":"official-plugins.md","filePath":"zh/official-plugins.md"}'),l={name:"official-plugins.md"};function o(s,a,r,d,c,h){return n(),t("div",null,a[0]||(a[0]=[i(`<h1 id="官方插件" tabindex="-1">官方插件 <a class="header-anchor" href="#官方插件" aria-label="Permalink to &quot;官方插件&quot;">​</a></h1><p>Uniquenium 官方插件包提供了一套常用的组件扩展，覆盖系统监控、网络信息、天气、日历等场景。安装官方插件后，桌面即可立即获得丰富的开箱即用组件。</p><h2 id="插件列表" tabindex="-1">插件列表 <a class="header-anchor" href="#插件列表" aria-label="Permalink to &quot;插件列表&quot;">​</a></h2><p>官方插件包（<code>Uniquenium-Official-Plugins</code>）通常包含：</p><table tabindex="0"><thead><tr><th>插件</th><th>组件</th><th>说明</th></tr></thead><tbody><tr><td><strong>SystemMonitor</strong></td><td>CPUMonitor、MemoryMonitor、NetMonitor、BatteryMonitor</td><td>实时系统监控</td></tr><tr><td><strong>Weather</strong></td><td>WeatherCard、WeatherForecast</td><td>天气显示（需 API Key）</td></tr><tr><td><strong>Calendar</strong></td><td>CalendarCard、ClockCard</td><td>日历与时钟组件</td></tr><tr><td><strong>Media</strong></td><td>MediaPlayer、VolumeControl</td><td>媒体播放与音量控制</td></tr><tr><td><strong>QuickNote</strong></td><td>NotePad、TodoList</td><td>便签与待办事项</td></tr></tbody></table><blockquote><p>插件列表可能随版本变化，最新列表请参考官方仓库。</p></blockquote><h2 id="安装方式" tabindex="-1">安装方式 <a class="header-anchor" href="#安装方式" aria-label="Permalink to &quot;安装方式&quot;">​</a></h2><h3 id="方式一-安装程序安装-推荐" tabindex="-1">方式一：安装程序安装（推荐） <a class="header-anchor" href="#方式一-安装程序安装-推荐" aria-label="Permalink to &quot;方式一：安装程序安装（推荐）&quot;">​</a></h3><ol><li>从 Releases 页面下载 <code>Uniquenium-Plugins-Setup-*.exe</code></li><li>运行安装程序，选择 Uniquenium 安装目录</li><li>安装完成后，插件自动放置于 <code>plugins/</code> 目录下</li><li>启动 Uniquenium，在 <strong>设置 → 插件</strong> 中查看已安装插件</li></ol><h3 id="方式二-手动安装" tabindex="-1">方式二：手动安装 <a class="header-anchor" href="#方式二-手动安装" aria-label="Permalink to &quot;方式二：手动安装&quot;">​</a></h3><ol><li>从 <a href="https://github.com/Uniquenium/Official-Plugins" target="_blank" rel="noreferrer">官方插件仓库</a> 下载最新 Release</li><li>将 DLL 文件解压到 <code>&lt;Uniquenium 安装目录&gt;/plugins/</code> 下的子目录中</li><li>启动 Uniquenium，插件会自动扫描并加载</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Uniquenium/</span></span>
<span class="line"><span>├── Uniquenium.exe</span></span>
<span class="line"><span>├── plugins/</span></span>
<span class="line"><span>│   ├── SystemMonitor/</span></span>
<span class="line"><span>│   │   └── SystemMonitor.dll</span></span>
<span class="line"><span>│   ├── Weather/</span></span>
<span class="line"><span>│   │   └── Weather.dll</span></span>
<span class="line"><span>│   └── Calendar/</span></span>
<span class="line"><span>│       └── Calendar.dll</span></span></code></pre></div><h3 id="方式三-应用内安装" tabindex="-1">方式三：应用内安装 <a class="header-anchor" href="#方式三-应用内安装" aria-label="Permalink to &quot;方式三：应用内安装&quot;">​</a></h3><ol><li>打开 Uniquenium 设置</li><li>切换到 <strong>插件</strong> 标签</li><li>点击 <strong>从本地安装</strong> 选择已下载的插件包</li><li>或点击 <strong>检查更新</strong> 从远程仓库获取最新插件</li></ol><h2 id="配置插件" tabindex="-1">配置插件 <a class="header-anchor" href="#配置插件" aria-label="Permalink to &quot;配置插件&quot;">​</a></h2><p>部分插件需要额外配置。以天气插件为例：</p><ol><li>在组件编辑器中从插件分类拖拽一个 <code>WeatherCard</code></li><li>右键组件 → <strong>属性</strong> → 填写 API Key 与城市</li><li>或在 <strong>设置 → 插件</strong> 标签中进行全局配置</li></ol><h2 id="卸载插件" tabindex="-1">卸载插件 <a class="header-anchor" href="#卸载插件" aria-label="Permalink to &quot;卸载插件&quot;">​</a></h2><ol><li>打开 <strong>设置 → 插件</strong></li><li>找到要移除的插件</li><li>点击 <strong>卸载</strong> 按钮</li><li>或直接删除 <code>plugins/</code> 下对应的子目录</li></ol><h2 id="开发插件" tabindex="-1">开发插件 <a class="header-anchor" href="#开发插件" aria-label="Permalink to &quot;开发插件&quot;">​</a></h2><p>如需开发自定义插件，请参考 <a href="./custom-developing/plugin">插件开发指南</a> 和 <a href="./controls-reference/cpp-ext/UniDeskPluginInterface">UniDeskPluginInterface</a>。</p><h2 id="备注" tabindex="-1">备注 <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注&quot;">​</a></h2><ul><li>官方插件必须与 Uniquenium 主程序的主版本匹配。</li><li>运行时加载失败的插件不会影响主程序稳定性，系统会跳过失败插件继续加载其他插件。</li><li>请仅从可信来源安装第三方插件。</li></ul>`,23)]))}const g=e(l,[["render",o]]);export{u as __pageData,g as default};
